    { const char * tb_v486 = "        uint32_t d = (uint32_t)b, hi = (uint32_t)(a >> 32), lo = (uint32_t)a, qh = hi / d, rh = hi % d, ql, rl;\n"; *(const char * *)tb_grow(v_lines) = tb_v486; }
