    { const char * tb_v1224 = "// начало программы на Windows: русский текст в консоли, цвета, слова запуска в UTF-8,\n"; *(const char * *)tb_grow(v_lines) = tb_v1224; }
    { const char * tb_v1225 = "// понятное сообщение при переполнении стека\n"; *(const char * *)tb_grow(v_lines) = tb_v1225; }
    { const char * tb_v1226 = "TB_API void tb_win_init(int *argc, char ***argv) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1226; }
