    { const char * tb_v1422 = "TB_INL tb_gpage *tb_gmap_get(uintptr_t a) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1422; }
    { const char * tb_v1423 = "    if (a >> 48) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1423; }
