    { const char * tb_v1428 = "    tb_gpage ***d = &tb_gdir[a >> 32];\n"; *(const char * *)tb_grow(v_lines) = tb_v1428; }
    { const char * tb_v1429 = "    if (!*d) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1429; }
    { const char * tb_v1430 = "        *d = calloc(1 << 16, sizeof(tb_gpage *));\n"; *(const char * *)tb_grow(v_lines) = tb_v1430; }
    { const char * tb_v1431 = "        if (!*d) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v1431; }
