    { const char * tb_v1436 = "    for (long long o = 0; o < size; o += TB_GPG) tb_gmap_put((uintptr_t)pg->start + o, pg);\n"; *(const char * *)tb_grow(v_lines) = tb_v1436; }
    { const char * tb_v1437 = "    if ((uintptr_t)pg->start < tb_glo) tb_glo = (uintptr_t)pg->start;\n"; *(const char * *)tb_grow(v_lines) = tb_v1437; }
