    { const char * tb_v1442 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1442; }
    { const char * tb_v1443 = "// память у системы: mmap всегда отдаёт нули и выровнено по 64 КБ (лишнее по краям отдаём назад)\n"; *(const char * *)tb_grow(v_lines) = tb_v1443; }
