    { const char * tb_v2359 = "// ---------- JSON: json_get(текст, \"users.0.name\") и json_text(текст) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v2359; }
    { const char * tb_v2360 = "TB_API const char *tb_js_ws(const char *p) { while (*p == ' ' || *p == '\\n' || *p == '\\r' || *p == '\\t') p++; return p; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2360; }
    { const char * tb_v2361 = "// пропустить одно значение; адрес после него или 0, если JSON сломан\n"; *(const char * *)tb_grow(v_lines) = tb_v2361; }
    { const char * tb_v2362 = "TB_API const char *tb_js_skip(const char *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2362; }
    { const char * tb_v2363 = "    p = tb_js_ws(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v2363; }
    { const char * tb_v2364 = "    if (*p == '\"') {\n"; *(const char * *)tb_grow(v_lines) = tb_v2364; }
    { const char * tb_v2365 = "        p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v2365; }
    { const char * tb_v2366 = "        while (*p && *p != '\"') { if (*p == '\\\\' && p[1]) p++; p++; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2366; }
    { const char * tb_v2367 = "        return *p ? p + 1 : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2367; }
    { const char * tb_v2368 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2368; }
    { const char * tb_v2369 = "    if (*p == '{' || *p == '[') {\n"; *(const char * *)tb_grow(v_lines) = tb_v2369; }
    { const char * tb_v2370 = "        int d = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2370; }
    { const char * tb_v2371 = "        while (*p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2371; }
    { const char * tb_v2372 = "            if (*p == '\"') { p = tb_js_skip(p); if (!p) return 0; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2372; }
    { const char * tb_v2373 = "            if (*p == '{' || *p == '[') d++;\n"; *(const char * *)tb_grow(v_lines) = tb_v2373; }
