    { const char * tb_v2554 = "TB_API void tb_sort_list(tb_list *l, int (*cmp)(const void *, const void *)) { qsort(l->data, l->len, l->size, cmp); }\n"; *(const char * *)tb_grow(v_lines) = tb_v2554; }
    { const char * tb_v2555 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v2555; }
    { const char * tb_v2556 = "// ---------- dict: ключи и значения лежат в двух списках по порядку добавления,\n"; *(const char * *)tb_grow(v_lines) = tb_v2556; }
    { const char * tb_v2557 = "// а найти номер по ключу можно тремя способами (mode):\n"; *(const char * *)tb_grow(v_lines) = tb_v2557; }
    { const char * tb_v2558 = "//   1 — «номер = адрес»: ключи int шли подряд base, base+1, base+2 ... — номер = ключ - base, без поиска;\n"; *(const char * *)tb_grow(v_lines) = tb_v2558; }
    { const char * tb_v2559 = "//   2 — «адресное хранение»: ключи int лежат плотно — pos[ключ - base] = номер + 1, один взгляд;\n"; *(const char * *)tb_grow(v_lines) = tb_v2559; }
    { const char * tb_v2560 = "//   0 — таблица slots с хешем (текст или разбросанные числа) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v2560; }
    { const char * tb_v2561 = "typedef struct {\n"; *(const char * *)tb_grow(v_lines) = tb_v2561; }
    { const char * tb_v2562 = "    tb_list *keys; tb_list *vals; long long *slots; long long nslots; int text;\n"; *(const char * *)tb_grow(v_lines) = tb_v2562; }
    { const char * tb_v2563 = "    int mode; long long base; long long *pos; long long npos;\n"; *(const char * *)tb_grow(v_lines) = tb_v2563; }
    { const char * tb_v2564 = "} tb_dict;\n"; *(const char * *)tb_grow(v_lines) = tb_v2564; }
    { const char * tb_v2565 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v2565; }
    { const char * tb_v2566 = "// ячейка таблицы: номер ключа + 1 (младшие 40 бит) и метка из старших битов хеша\n"; *(const char * *)tb_grow(v_lines) = tb_v2566; }
    { const char * tb_v2567 = "#define TB_DAT ((1LL << 40) - 1)\n"; *(const char * *)tb_grow(v_lines) = tb_v2567; }
    { const char * tb_v2568 = "#define TB_DTAG(h) ((long long)(((h) >> 40) << 40) & ~TB_DAT & 0x7FFFFFFFFFFFFFFFLL)\n"; *(const char * *)tb_grow(v_lines) = tb_v2568; }
    { const char * tb_v2569 = "TB_API unsigned long long tb_hash(tb_dict *d, const void *k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2569; }
    { const char * tb_v2570 = "    unsigned long long h = 1469598103934665603ULL;\n"; *(const char * *)tb_grow(v_lines) = tb_v2570; }
    { const char * tb_v2571 = "    if (d->text) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2571; }
    { const char * tb_v2572 = "        for (const unsigned char *p = *(const unsigned char * const *)k; *p; p++) { h ^= *p; h *= 1099511628211ULL; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2572; }
    { const char * tb_v2573 = "    } else {\n"; *(const char * *)tb_grow(v_lines) = tb_v2573; }
    { const char * tb_v2574 = "        h ^= (unsigned long long)*(const long long *)k;\n"; *(const char * *)tb_grow(v_lines) = tb_v2574; }
    { const char * tb_v2575 = "        h *= 0x9E3779B97F4A7C15ULL;\n"; *(const char * *)tb_grow(v_lines) = tb_v2575; }
    { const char * tb_v2576 = "        h ^= h >> 32;\n"; *(const char * *)tb_grow(v_lines) = tb_v2576; }
    { const char * tb_v2577 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2577; }
    { const char * tb_v2578 = "    return h;\n"; *(const char * *)tb_grow(v_lines) = tb_v2578; }
    { const char * tb_v2579 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2579; }
    { const char * tb_v2580 = "TB_API int tb_keq(tb_dict *d, const void *a, const void *b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2580; }
    { const char * tb_v2581 = "    if (d->text) return strcmp(*(const char * const *)a, *(const char * const *)b) == 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2581; }
    { const char * tb_v2582 = "    return *(const long long *)a == *(const long long *)b;\n"; *(const char * *)tb_grow(v_lines) = tb_v2582; }
    { const char * tb_v2583 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2583; }
    { const char * tb_v2584 = "TB_INL long long tb_dfind(tb_dict *d, const void *k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2584; }
    { const char * tb_v2585 = "    if (d->mode == 1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2585; }
    { const char * tb_v2586 = "        unsigned long long at = (unsigned long long)(*(const long long *)k - d->base);\n"; *(const char * *)tb_grow(v_lines) = tb_v2586; }
    { const char * tb_v2587 = "        return at < (unsigned long long)d->keys->len ? (long long)at : -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2587; }
    { const char * tb_v2588 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2588; }
    { const char * tb_v2589 = "    if (d->mode == 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2589; }
    { const char * tb_v2590 = "        unsigned long long o = (unsigned long long)(*(const long long *)k - d->base);\n"; *(const char * *)tb_grow(v_lines) = tb_v2590; }
    { const char * tb_v2591 = "        return o < (unsigned long long)d->npos ? d->pos[o] - 1 : -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2591; }
    { const char * tb_v2592 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2592; }
    { const char * tb_v2593 = "    unsigned long long h = tb_hash(d, k), mask = d->nslots - 1, i = h & mask;\n"; *(const char * *)tb_grow(v_lines) = tb_v2593; }
    { const char * tb_v2594 = "    long long tag = TB_DTAG(h);\n"; *(const char * *)tb_grow(v_lines) = tb_v2594; }
    { const char * tb_v2595 = "    while (d->slots[i] != 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2595; }
    { const char * tb_v2596 = "        long long sl = d->slots[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v2596; }
    { const char * tb_v2597 = "        // метка хеша совпала — только тогда сравниваем сами ключи (текст — дорого)\n"; *(const char * *)tb_grow(v_lines) = tb_v2597; }
    { const char * tb_v2598 = "        if ((sl & ~TB_DAT) == tag) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2598; }
    { const char * tb_v2599 = "            long long at = (sl & TB_DAT) - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2599; }
    { const char * tb_v2600 = "            if (tb_keq(d, d->keys->data + at * d->keys->size, k)) return at;\n"; *(const char * *)tb_grow(v_lines) = tb_v2600; }
    { const char * tb_v2601 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v2601; }
    { const char * tb_v2602 = "        i = (i + 1) & mask;\n"; *(const char * *)tb_grow(v_lines) = tb_v2602; }
    { const char * tb_v2603 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2603; }
    { const char * tb_v2604 = "    return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2604; }
    { const char * tb_v2605 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2605; }
    { const char * tb_v2606 = "// память для таблиц dict — там же, где лежат его ключи (временная или обычная)\n"; *(const char * *)tb_grow(v_lines) = tb_v2606; }
    { const char * tb_v2607 = "TB_API void *tb_dalloc(tb_dict *d, void *old, long long bytes) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2607; }
    { const char * tb_v2608 = "    if (old && !(tb_nchunks > 0 && tb_in_temp(old))) tb_gc_free(old);\n"; *(const char * *)tb_grow(v_lines) = tb_v2608; }
    { const char * tb_v2609 = "    void *p = tb_in_cur_temp(d->keys->data) ? tb_temp_alloc(bytes) : tb_gc_alloc_np(bytes);\n"; *(const char * *)tb_grow(v_lines) = tb_v2609; }
    { const char * tb_v2610 = "    if (!p) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2610; }
    { const char * tb_v2611 = "    return p;\n"; *(const char * *)tb_grow(v_lines) = tb_v2611; }
    { const char * tb_v2612 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2612; }
    { const char * tb_v2613 = "TB_API void tb_dreindex(tb_dict *d, long long nslots) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2613; }
    { const char * tb_v2614 = "    d->mode = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2614; }
    { const char * tb_v2615 = "    if (d->pos) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2615; }
    { const char * tb_v2616 = "        if (!(tb_nchunks > 0 && tb_in_temp(d->pos))) tb_gc_free(d->pos);\n"; *(const char * *)tb_grow(v_lines) = tb_v2616; }
    { const char * tb_v2617 = "        d->pos = 0; d->npos = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2617; }
    { const char * tb_v2618 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2618; }
    { const char * tb_v2619 = "    d->nslots = nslots;\n"; *(const char * *)tb_grow(v_lines) = tb_v2619; }
    { const char * tb_v2620 = "    d->slots = tb_dalloc(d, d->slots, nslots * sizeof(long long));\n"; *(const char * *)tb_grow(v_lines) = tb_v2620; }
    { const char * tb_v2621 = "    memset(d->slots, 0, nslots * sizeof(long long));\n"; *(const char * *)tb_grow(v_lines) = tb_v2621; }
    { const char * tb_v2622 = "    unsigned long long mask = nslots - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2622; }
    { const char * tb_v2623 = "    for (long long at = 0; at < d->keys->len; at++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2623; }
    { const char * tb_v2624 = "        unsigned long long h = tb_hash(d, d->keys->data + at * d->keys->size), i = h & mask;\n"; *(const char * *)tb_grow(v_lines) = tb_v2624; }
    { const char * tb_v2625 = "        while (d->slots[i] != 0) i = (i + 1) & mask;\n"; *(const char * *)tb_grow(v_lines) = tb_v2625; }
    { const char * tb_v2626 = "        d->slots[i] = (at + 1) | TB_DTAG(h);\n"; *(const char * *)tb_grow(v_lines) = tb_v2626; }
    { const char * tb_v2627 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2627; }
    { const char * tb_v2628 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2628; }
    { const char * tb_v2629 = "// перейти на таблицу с хешем (ключ ушёл далеко от остальных или его удалили)\n"; *(const char * *)tb_grow(v_lines) = tb_v2629; }
    { const char * tb_v2630 = "TB_API void tb_dto_hash(tb_dict *d) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2630; }
    { const char * tb_v2631 = "    long long n = 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v2631; }
    { const char * tb_v2632 = "    while (n < d->keys->len * 2 + 2) n *= 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v2632; }
    { const char * tb_v2633 = "    tb_dreindex(d, n);\n"; *(const char * *)tb_grow(v_lines) = tb_v2633; }
    { const char * tb_v2634 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2634; }
    { const char * tb_v2635 = "// mode 2: таблица pos на ключи base .. base+npos-1\n"; *(const char * *)tb_grow(v_lines) = tb_v2635; }
    { const char * tb_v2636 = "TB_API void tb_dto_pos(tb_dict *d, long long npos) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2636; }
    { const char * tb_v2637 = "    long long *p = tb_dalloc(d, 0, npos * sizeof(long long));\n"; *(const char * *)tb_grow(v_lines) = tb_v2637; }
    { const char * tb_v2638 = "    memset(p, 0, npos * sizeof(long long));\n"; *(const char * *)tb_grow(v_lines) = tb_v2638; }
    { const char * tb_v2639 = "    const long long *ks = (const long long *)d->keys->data;\n"; *(const char * *)tb_grow(v_lines) = tb_v2639; }
    { const char * tb_v2640 = "    for (long long at = 0; at < d->keys->len; at++) p[ks[at] - d->base] = at + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2640; }
    { const char * tb_v2641 = "    if (d->pos && !(tb_nchunks > 0 && tb_in_temp(d->pos))) tb_gc_free(d->pos);\n"; *(const char * *)tb_grow(v_lines) = tb_v2641; }
    { const char * tb_v2642 = "    d->pos = p;\n"; *(const char * *)tb_grow(v_lines) = tb_v2642; }
    { const char * tb_v2643 = "    d->npos = npos;\n"; *(const char * *)tb_grow(v_lines) = tb_v2643; }
    { const char * tb_v2644 = "    d->mode = 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v2644; }
    { const char * tb_v2645 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2645; }
    { const char * tb_v2646 = "TB_API tb_dict *tb_dict_new(int text, long long vsize) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2646; }
    { const char * tb_v2647 = "    tb_dict *d = tb_mem(sizeof(tb_dict));\n"; *(const char * *)tb_grow(v_lines) = tb_v2647; }
    { const char * tb_v2648 = "    d->text = text;\n"; *(const char * *)tb_grow(v_lines) = tb_v2648; }
    { const char * tb_v2649 = "    d->keys = text ? tb_list_new(sizeof(const char *)) : tb_list_new_np(sizeof(long long));\n"; *(const char * *)tb_grow(v_lines) = tb_v2649; }
    { const char * tb_v2650 = "    d->vals = tb_list_new(vsize);\n"; *(const char * *)tb_grow(v_lines) = tb_v2650; }
    { const char * tb_v2651 = "    d->slots = 0; d->pos = 0; d->npos = 0; d->base = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2651; }
    { const char * tb_v2652 = "    if (text) tb_dreindex(d, 8);\n"; *(const char * *)tb_grow(v_lines) = tb_v2652; }
    { const char * tb_v2653 = "    else { d->mode = 1; d->nslots = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2653; }
    { const char * tb_v2654 = "    return d;\n"; *(const char * *)tb_grow(v_lines) = tb_v2654; }
    { const char * tb_v2655 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2655; }
    { const char * tb_v2656 = "// .clear(): список снова пустой; свой кусок памяти отдаётся (если он не временный).\n"; *(const char * *)tb_grow(v_lines) = tb_v2656; }
    { const char * tb_v2657 = "// Тексты и obj внутри не удаляются: на них могут смотреть другие переменные.\n"; *(const char * *)tb_grow(v_lines) = tb_v2657; }
    { const char * tb_v2658 = "TB_API void tb_lclear(tb_list *l, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2658; }
    { const char * tb_v2659 = "    if (l->cap < 0) tb_crash(line, \".clear() нельзя, пока по списку идёт each ... by N\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2659; }
    { const char * tb_v2660 = "    int temp = tb_nchunks > 0 && tb_in_temp(l->data);\n"; *(const char * *)tb_grow(v_lines) = tb_v2660; }
    { const char * tb_v2661 = "    if (!temp) tb_gc_free(l->data);\n"; *(const char * *)tb_grow(v_lines) = tb_v2661; }
    { const char * tb_v2662 = "    long long cap = l->size == 0 ? 64 : 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v2662; }
    { const char * tb_v2663 = "    long long bytes = l->size == 0 ? 8 : l->size * 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v2663; }
