    { const char * tb_v2673 = "    if (d->slots && !(tb_nchunks > 0 && tb_in_temp(d->slots))) tb_gc_free(d->slots);\n"; *(const char * *)tb_grow(v_lines) = tb_v2673; }
    { const char * tb_v2674 = "    d->slots = 0; d->pos = 0; d->npos = 0; d->base = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2674; }
