    { const char * tb_v2698 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2698; }
    { const char * tb_v2699 = "// место под значение ключа k; если ключа нет — добавить со значением *def\n"; *(const char * *)tb_grow(v_lines) = tb_v2699; }
    { const char * tb_v2700 = "TB_API void *tb_dput(tb_dict *d, const void *k, const void *def) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2700; }
    { const char * tb_v2701 = "    long long at = tb_dfind(d, k);\n"; *(const char * *)tb_grow(v_lines) = tb_v2701; }
    { const char * tb_v2702 = "    if (at >= 0) return d->vals->data + at * d->vals->size;\n"; *(const char * *)tb_grow(v_lines) = tb_v2702; }
    { const char * tb_v2703 = "    memcpy(tb_grow(d->keys), k, d->keys->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v2703; }
