    { const char * tb_v2706 = "    if (d->mode != 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2706; }
    { const char * tb_v2707 = "        // без поиска; если ключ лёг далеко, tb_dplace_int сам перейдёт на хеш и впишет все ключи\n"; *(const char * *)tb_grow(v_lines) = tb_v2707; }
    { const char * tb_v2708 = "        tb_dplace_int(d, *(const long long *)k);\n"; *(const char * *)tb_grow(v_lines) = tb_v2708; }
