    { const char * tb_v2710 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2710; }
    { const char * tb_v2711 = "    if (d->keys->len * 2 > d->nslots) tb_dreindex(d, d->nslots * 2);\n"; *(const char * *)tb_grow(v_lines) = tb_v2711; }
    { const char * tb_v2712 = "    else {\n"; *(const char * *)tb_grow(v_lines) = tb_v2712; }
    { const char * tb_v2713 = "        unsigned long long h = tb_hash(d, k), mask = d->nslots - 1, i = h & mask;\n"; *(const char * *)tb_grow(v_lines) = tb_v2713; }
