    { const char * tb_v2804 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2804; }
    { const char * tb_v2805 = "TB_API tb_dict *tb_dict_from(int text, long long vsize, long long n, const void *keys, const void *vals) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2805; }
    { const char * tb_v2806 = "    tb_dict *d = tb_dict_new(text, vsize);\n"; *(const char * *)tb_grow(v_lines) = tb_v2806; }
