    { const char * tb_v2836 = "// Готовые потоки: создаются один раз (при первом on all cores) и ждут работу.\n"; *(const char * *)tb_grow(v_lines) = tb_v2836; }
    { const char * tb_v2837 = "// Раньше каждый цикл на ядрах создавал и закрывал потоки — для коротких циклов это было дольше самой работы.\n"; *(const char * *)tb_grow(v_lines) = tb_v2837; }
    { const char * tb_v2838 = "TB_API pthread_mutex_t tb_pool_m = PTHREAD_MUTEX_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v2838; }
    { const char * tb_v2839 = "TB_API pthread_cond_t tb_pool_go = PTHREAD_COND_INITIALIZER, tb_pool_end = PTHREAD_COND_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v2839; }
    { const char * tb_v2840 = "TB_API int tb_pool_n = 0, tb_pool_want = 0, tb_pool_busy = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2840; }
    { const char * tb_v2841 = "TB_API volatile long long tb_pool_gen = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2841; }
    { const char * tb_v2842 = "TB_API volatile int tb_pool_left = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2842; }
    { const char * tb_v2843 = "TB_API void *(*tb_pool_work)(void *) = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2843; }
    { const char * tb_v2844 = "TB_API void *tb_pool_job = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2844; }
    { const char * tb_v2845 = "TB_API void *tb_pool_loop(void *arg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2845; }
    { const char * tb_v2846 = "    int me = (int)(long long)arg;\n"; *(const char * *)tb_grow(v_lines) = tb_v2846; }
    { const char * tb_v2847 = "    // поток пула не считается «работающим», пока ждёт: уборка памяти может идти\n"; *(const char * *)tb_grow(v_lines) = tb_v2847; }
    { const char * tb_v2848 = "    __atomic_sub_fetch(&tb_gthreads, 1, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v2848; }
    { const char * tb_v2849 = "    long long seen = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2849; }
    { const char * tb_v2850 = "    for (;;) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2850; }
    { const char * tb_v2851 = "        // немного ждём без сна: циклы на ядрах часто идут один за другим\n"; *(const char * *)tb_grow(v_lines) = tb_v2851; }
    { const char * tb_v2852 = "        for (int spin = 0; spin < 20000 && __atomic_load_n(&tb_pool_gen, __ATOMIC_ACQUIRE) == seen; spin++)\n"; *(const char * *)tb_grow(v_lines) = tb_v2852; }
    { const char * tb_v2853 = "            __builtin_ia32_pause_or_yield();\n"; *(const char * *)tb_grow(v_lines) = tb_v2853; }
    { const char * tb_v2854 = "        pthread_mutex_lock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v2854; }
    { const char * tb_v2855 = "        while (tb_pool_gen == seen) pthread_cond_wait(&tb_pool_go, &tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v2855; }
    { const char * tb_v2856 = "        seen = tb_pool_gen;\n"; *(const char * *)tb_grow(v_lines) = tb_v2856; }
    { const char * tb_v2857 = "        int mine = me < tb_pool_want;\n"; *(const char * *)tb_grow(v_lines) = tb_v2857; }
    { const char * tb_v2858 = "        void *(*work)(void *) = tb_pool_work;\n"; *(const char * *)tb_grow(v_lines) = tb_v2858; }
    { const char * tb_v2859 = "        void *job = tb_pool_job;\n"; *(const char * *)tb_grow(v_lines) = tb_v2859; }
    { const char * tb_v2860 = "        pthread_mutex_unlock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v2860; }
    { const char * tb_v2861 = "        if (!mine) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v2861; }
    { const char * tb_v2862 = "        work(job);\n"; *(const char * *)tb_grow(v_lines) = tb_v2862; }
    { const char * tb_v2863 = "        __atomic_sub_fetch(&tb_gthreads, 1, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v2863; }
    { const char * tb_v2864 = "        if (__atomic_sub_fetch(&tb_pool_left, 1, __ATOMIC_ACQ_REL) == 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2864; }
    { const char * tb_v2865 = "            pthread_mutex_lock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v2865; }
    { const char * tb_v2866 = "            pthread_cond_signal(&tb_pool_end);\n"; *(const char * *)tb_grow(v_lines) = tb_v2866; }
    { const char * tb_v2867 = "            pthread_mutex_unlock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v2867; }
    { const char * tb_v2868 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v2868; }
    { const char * tb_v2869 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2869; }
    { const char * tb_v2870 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2870; }
    { const char * tb_v2871 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2871; }
    { const char * tb_v2872 = "TB_API void tb_par_run(void *(*work)(void *), void *job, long long total) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2872; }
    { const char * tb_v2873 = "    int n = tb_cores();\n"; *(const char * *)tb_grow(v_lines) = tb_v2873; }
    { const char * tb_v2874 = "    if (n > total) n = (int)total;\n"; *(const char * *)tb_grow(v_lines) = tb_v2874; }
    { const char * tb_v2875 = "    if (n < 1) n = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2875; }
    { const char * tb_v2876 = "    if (n == 1) { work(job); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2876; }
    { const char * tb_v2877 = "    // пул уже занят (цикл на ядрах из background или изнутри другого) — по-старому, своими потоками\n"; *(const char * *)tb_grow(v_lines) = tb_v2877; }
    { const char * tb_v2878 = "    if (__atomic_exchange_n(&tb_pool_busy, 1, __ATOMIC_ACQ_REL)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2878; }
    { const char * tb_v2879 = "        pthread_t t[256];\n"; *(const char * *)tb_grow(v_lines) = tb_v2879; }
    { const char * tb_v2880 = "        for (int i = 1; i < n; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v2880; }
    { const char * tb_v2881 = "            if (tb_thread_create(&t[i], work, job) != 0) tb_crash(0, \"не получилось запустить ядро\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2881; }
    { const char * tb_v2882 = "        work(job);\n"; *(const char * *)tb_grow(v_lines) = tb_v2882; }
    { const char * tb_v2883 = "        for (int i = 1; i < n; i++) pthread_join(t[i], 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v2883; }
    { const char * tb_v2884 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v2884; }
    { const char * tb_v2885 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2885; }
    { const char * tb_v2886 = "    while (tb_pool_n < n - 1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2886; }
    { const char * tb_v2887 = "        pthread_t th;\n"; *(const char * *)tb_grow(v_lines) = tb_v2887; }
    { const char * tb_v2888 = "        if (tb_thread_create(&th, tb_pool_loop, (void *)(long long)tb_pool_n) != 0) tb_crash(0, \"не получилось запустить ядро\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2888; }
    { const char * tb_v2889 = "        pthread_detach(th);\n"; *(const char * *)tb_grow(v_lines) = tb_v2889; }
    { const char * tb_v2890 = "        tb_pool_n++;\n"; *(const char * *)tb_grow(v_lines) = tb_v2890; }
    { const char * tb_v2891 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2891; }
    { const char * tb_v2892 = "    pthread_mutex_lock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v2892; }
    { const char * tb_v2893 = "    tb_pool_work = work; tb_pool_job = job; tb_pool_want = n - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2893; }
    { const char * tb_v2894 = "    __atomic_store_n(&tb_pool_left, n - 1, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v2894; }
    { const char * tb_v2895 = "    __atomic_add_fetch(&tb_gthreads, n - 1, __ATOMIC_ACQ_REL);\n"; *(const char * *)tb_grow(v_lines) = tb_v2895; }
    { const char * tb_v2896 = "    __atomic_add_fetch(&tb_pool_gen, 1, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v2896; }
    { const char * tb_v2897 = "    pthread_cond_broadcast(&tb_pool_go);\n"; *(const char * *)tb_grow(v_lines) = tb_v2897; }
    { const char * tb_v2898 = "    pthread_mutex_unlock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v2898; }
    { const char * tb_v2899 = "    work(job);\n"; *(const char * *)tb_grow(v_lines) = tb_v2899; }
    { const char * tb_v2900 = "    if (__atomic_load_n(&tb_pool_left, __ATOMIC_ACQUIRE) != 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2900; }
    { const char * tb_v2901 = "        for (int spin = 0; spin < 20000 && __atomic_load_n(&tb_pool_left, __ATOMIC_ACQUIRE) != 0; spin++)\n"; *(const char * *)tb_grow(v_lines) = tb_v2901; }
    { const char * tb_v2902 = "            __builtin_ia32_pause_or_yield();\n"; *(const char * *)tb_grow(v_lines) = tb_v2902; }
    { const char * tb_v2903 = "        pthread_mutex_lock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v2903; }
    { const char * tb_v2904 = "        while (__atomic_load_n(&tb_pool_left, __ATOMIC_ACQUIRE) != 0) pthread_cond_wait(&tb_pool_end, &tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v2904; }
    { const char * tb_v2905 = "        pthread_mutex_unlock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v2905; }
    { const char * tb_v2906 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2906; }
    { const char * tb_v2907 = "    __atomic_store_n(&tb_pool_busy, 0, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v2907; }
    { const char * tb_v2908 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2908; }
    { const char * tb_v2909 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v2909; }
    { const char * tb_v2910 = "TB_API long long tb_par_step(long long total) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2910; }
    { const char * tb_v2911 = "    long long s = total / ((long long)tb_cores() * 16);\n"; *(const char * *)tb_grow(v_lines) = tb_v2911; }
    { const char * tb_v2912 = "    return s < 1 ? 1 : s;\n"; *(const char * *)tb_grow(v_lines) = tb_v2912; }
    { const char * tb_v2913 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2913; }
    { const char * tb_v2914 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v2914; }
    { const char * tb_v2915 = "// ---------- биты, адреса, порты, замки (danger и lock) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v2915; }
    { const char * tb_v2916 = "TB_INL long long tb_band(long long a, long long b) { return a & b; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2916; }
    { const char * tb_v2917 = "TB_INL long long tb_bor(long long a, long long b) { return a | b; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2917; }
