    { const char * tb_v2921 = "TB_INL long long tb_shr(long long a, long long n) { return (long long)((unsigned long long)a >> (n & 63)); }\n"; *(const char * *)tb_grow(v_lines) = tb_v2921; }
    { const char * tb_v2922 = "// чтение и запись по адресу: volatile — компилятор C не выкинет и не переставит их\n"; *(const char * *)tb_grow(v_lines) = tb_v2922; }
