    { const char * tb_v2954 = "            else __builtin_ia32_pause();\n"; *(const char * *)tb_grow(v_lines) = tb_v2954; }
    { const char * tb_v2955 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v2955; }
    { const char * tb_v2956 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v2956; }
    { const char * tb_v2957 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2957; }
    { const char * tb_v2958 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2958; }
    { const char * tb_v2959 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2959; }
    { const char * tb_v2960 = "TB_INL void tb_lock_give(int *l, unsigned long f) { (void)f; __atomic_store_n(l, 0, __ATOMIC_RELEASE); }\n"; *(const char * *)tb_grow(v_lines) = tb_v2960; }
    { const char * tb_v2961 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v2961; }
    { const char * tb_v2962 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v2962; }
    { const char * tb_v2963 = "// ---------- канал: очередь между потоками (channel int / text ...) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v2963; }
    { const char * tb_v2964 = "// send кладёт в конец (очередь растёт, отправитель не ждёт), receive берёт из начала\n"; *(const char * *)tb_grow(v_lines) = tb_v2964; }
